// SPDX-License-Identifier: GPL-3.0-only
/**
 * gen-timeline-facts — derive the single-source timeline FACTS that the sim and
 * other pages consume, from the canonical timeline CSV (src/data/timeline_*.csv,
 * latest date wins). Emits src/data/timelineFacts.generated.ts. Run as a prebuild
 * step so editing the CSV + building propagates everywhere; `--check` fails CI if
 * the committed generated file is stale vs the CSV.
 *
 *   node scripts/gen-timeline-facts.mjs           # (re)generate
 *   node scripts/gen-timeline-facts.mjs --print   # print the derived table only
 *   node scripts/gen-timeline-facts.mjs --check    # exit 1 if stale (CI gate)
 *
 * Derivation rule (decision 2026-06-18): each country's COUNTRY_DEADLINE_YEAR =
 * the StartYear of the row a human TAGGED `is_sim_deadline=true` in the CSV (its
 * canonical PQC migration deadline — the flat `Category=Deadline` mixes legacy,
 * soft and protocol-specific rows, so the choice is curated in the CSV, not
 * heuristic). Untagged countries are omitted → the sim falls back to the Q-Day anchor.
 */
import { readFileSync, writeFileSync, readdirSync } from 'fs'
import { join, dirname } from 'path'
import { fileURLToPath } from 'url'
import Papa from 'papaparse'

const DATA = join(dirname(fileURLToPath(import.meta.url)), '..', 'src', 'data')
const OUT = join(DATA, 'timelineFacts.generated.ts')

// Latest dated timeline CSV (timeline_MMDDYYYY[_rN].csv).
function latestCsv() {
  const re = /^timeline_(\d{2})(\d{2})(\d{4})(?:_r(\d+))?\.csv$/
  let best = null
  for (const f of readdirSync(DATA)) {
    const m = f.match(re)
    if (!m) continue
    const key = `${m[3]}${m[1]}${m[2]}${(m[4] ?? '0').padStart(3, '0')}`
    if (!best || key > best.key) best = { key, file: f }
  }
  if (!best) throw new Error('no timeline_*.csv found')
  return best.file
}

// CSV uses ISO-3166 flags; the sim uses 'UK' for Great Britain.
const FLAG_TO_SIM = { GB: 'UK' }

// Emit an object key the way Prettier would (quoteProps: as-needed + singleQuote):
// bare when it's a valid identifier, else single-quoted. Keeps the generated file
// Prettier-stable so the `--check` gate doesn't fight the pre-commit formatter.
const propKey = (s) => (/^[A-Za-z_$][A-Za-z0-9_$]*$/.test(s) ? s : `'${s.replace(/'/g, "\\'")}'`)

function derive() {
  const file = latestCsv()
  const { data } = Papa.parse(readFileSync(join(DATA, file), 'utf8'), {
    header: true,
    skipEmptyLines: true,
  })
  const active = data.filter((r) => r.status !== 'deprecated')

  // The row each country tagged `is_sim_deadline=true` (curated canonical deadline).
  // Keyed by sim code (UK/US/…) for the sim/timeline, and by full Country NAME for
  // the assessment/report (whose country field is the full name) — one source, two keys.
  const deadline = {}
  const deadlineByName = {}
  for (const r of active) {
    if (r.is_sim_deadline !== 'true') continue
    const code = FLAG_TO_SIM[r.FlagCode] ?? r.FlagCode
    const yr = parseInt(r.StartYear, 10)
    if (!code || !Number.isFinite(yr)) continue
    const mandate = (r.mandate_type ?? '').trim() || 'NONE'
    deadline[code] = { year: yr, title: r.Title, mandate }
    const name = (r.Country ?? '').trim()
    if (name) deadlineByName[name] = { year: yr, title: r.Title, mandate }
  }
  // Per-country scenario milestones tagged `sim_milestone` (hndl-critical, tnfl-critical,
  // governance). Drives the scenario-configurable sim; general-asset + governance dates that
  // aren't tagged are derived downstream in scenarioConfig.
  const milestones = {}
  for (const r of active) {
    const key = (r.sim_milestone ?? '').trim() // last-column values can carry a trailing CR/LF
    if (!key) continue
    const code = FLAG_TO_SIM[r.FlagCode] ?? r.FlagCode
    const yr = parseInt(r.StartYear, 10)
    if (!code || !Number.isFinite(yr)) continue
    ;(milestones[code] ??= {})[key] = yr
  }
  return { file, deadline, deadlineByName, milestones }
}

function generate({ file, deadline, deadlineByName, milestones }) {
  const codes = Object.keys(deadline).sort()
  const lines = codes.map((c) => `  ${c}: ${deadline[c].year}, // ${deadline[c].title}`)
  const names = Object.keys(deadlineByName).sort()
  const nlines = names.map(
    (n) => `  ${propKey(n)}: ${deadlineByName[n].year}, // ${deadlineByName[n].title}`
  )
  const mandateLines = codes.map((c) => `  ${c}: '${deadline[c].mandate}',`)
  const mandateNameLines = names.map((n) => `  ${propKey(n)}: '${deadlineByName[n].mandate}',`)
  const mcodes = Object.keys(milestones).sort()
  const mlines = mcodes.map((c) => {
    const entries = Object.entries(milestones[c])
      .sort()
      .map(([k, y]) => `'${k}': ${y}`)
      .join(', ')
    return `  ${c}: { ${entries} },`
  })
  return `// SPDX-License-Identifier: GPL-3.0-only
// GENERATED by scripts/gen-timeline-facts.mjs from ${file} — DO NOT EDIT BY HAND.
// Edit the timeline CSV and re-run \`npm run gen:timeline-facts\` (runs in prebuild).
// Single source of truth: the timeline reference CSV.

/** Each country's canonical PQC migration deadline — the row tagged
 *  \`is_sim_deadline=true\` in the timeline CSV. Untagged countries fall back to
 *  the Q-Day anchor in moscaClock. */
export const TIMELINE_COUNTRY_DEADLINE_YEAR: Record<string, number> = {
${lines.join('\n')}
}

/** The same canonical deadlines keyed by full country NAME (matches the
 *  assessment's \`country\` field). This is the single source the assessment and
 *  the report read — it replaced the former hand-coded COUNTRY_PLANNING_HORIZON,
 *  so Assess/Report now agree with the Timeline and the Simulation. Countries
 *  without a tagged CSV deadline are omitted and fall back via the consumer's
 *  EU-member / Q-Day logic. */
export const TIMELINE_COUNTRY_DEADLINE_BY_NAME: Record<string, number> = {
${nlines.join('\n')}
}

export type DeadlineMandate = 'HARD' | 'SOFT' | 'DRAFT' | 'NONE'

/** Whether each country's canonical deadline is a binding legal mandate (\`HARD\` —
 *  law, regulation, executive order, binding directive) or soft guidance / roadmap /
 *  strategy (\`SOFT\`), from the timeline CSV \`mandate_type\` column. Lets the UI label
 *  "regulatory deadline" vs "guidance target" instead of presenting every government
 *  date as binding. Keyed by sim code and by full country name. */
export const TIMELINE_COUNTRY_DEADLINE_MANDATE: Record<string, DeadlineMandate> = {
${mandateLines.join('\n')}
}

export const TIMELINE_COUNTRY_DEADLINE_MANDATE_BY_NAME: Record<string, DeadlineMandate> = {
${mandateNameLines.join('\n')}
}

/** Per-country scenario milestone years, from rows tagged \`sim_milestone\` in the
 *  timeline CSV (e.g. 'hndl-critical', 'tnfl-critical', 'governance'). Powers the
 *  scenario-configurable simulation; untagged milestones (general-asset, governance)
 *  are derived in scenarioConfig. */
export const TIMELINE_COUNTRY_MILESTONES: Record<string, Partial<Record<string, number>>> = {
${mlines.join('\n')}
}
`
}

const args = process.argv.slice(2)
const derived = derive()

if (args.includes('--print')) {
  console.log(`source: ${derived.file}\n`)
  for (const [c, v] of Object.entries(derived.deadline).sort())
    console.log(`  ${c.padEnd(3)} ${v.year}  ${v.title}`)
  process.exit(0)
}

const next = generate(derived)
if (args.includes('--check')) {
  let current = ''
  try {
    current = readFileSync(OUT, 'utf8')
  } catch {
    /* missing → stale */
  }
  if (current !== next) {
    console.error(`✗ ${OUT} is stale vs ${derived.file} — run \`npm run gen:timeline-facts\``)
    process.exit(1)
  }
  console.log('✓ timeline facts up to date')
  process.exit(0)
}

writeFileSync(OUT, next)
console.log(`wrote ${OUT} from ${derived.file} (${Object.keys(derived.deadline).length} countries)`)
